import { HistogramAdapter } from '@dreadnought/react/unstyled';
const data = [42, 65, 110, 125, 180, 210, 320, 580];
export function Example() { return <HistogramAdapter label="Время ответа" data={data} bins={6} domain={[0,600]} categoryLabel="Время, мс" valueLabel="Запросы" />; }

import { HistogramAdapter, useHistogram } from '@dreadnought/react/unstyled';
const data = [0,1,2,3,4];
function Summary() { const {layout,page} = useHistogram(); return <button onClick={() => page.change(2)}>Страница {page.page}, измерений {layout.total}</button>; }
export function Example() { return <HistogramAdapter label="Распределение" data={data} bins={2} pageSize={1}><Summary /><HistogramAdapter.Plot tooltipContent={({defaultContent}) => <div>{defaultContent}</div>}>{({defaultContent}) => defaultContent}</HistogramAdapter.Plot><HistogramAdapter.Table /><HistogramAdapter.Pagination /><HistogramAdapter.Empty /></HistogramAdapter>; }
